  "Buy {n1} items (seals or artifacts) in one round": "Αγόρασε {n1} αντικείμενα (σφραγίδες ή κειμήλια) σε έναν γύρο",
  "Buy {price}": "Αγορά {price}",
  "Buying an offering resets stacks.": "Η αγορά μιας προσφοράς μηδενίζει τις στοίβες.",
  "CRITICALS in a row": "CRITICAL στη σειρά",
