  "Regardless, this display of defiance can't go any longer.": "Όπως και να 'χει, αυτή η επίδειξη ανυπακοής δεν μπορεί να συνεχιστεί άλλο.",
  "Remember the rules, you have to defeat ALL other Damned, and if my eyes don't deceive me I can definitely see many more left, ain't that right?": "Θυμήσου τους κανόνες, πρέπει να νικήσεις ΟΛΟΥΣ τους άλλους Καταδικασμένους, και αν δεν με απατούν τα μάτια μου βλέπω σίγουρα πολλούς ακόμα, δεν είναι έτσι;",
