  "Reveal": "Αποκάλυψη",
  "Revealed DAMNED become STUBBORN.": "Οι αποκαλυμμένοι ΚΑΤΑΔΙΚΑΣΜΕΝΟΙ γίνονται ΠΕΙΣΜΑΤΑΡΗΔΕΣ.",
  "Revealed DAMNED gain +{n1} BOUNTY and +{n2} MEMORY permanently.": "Οι αποκαλυμμένοι ΚΑΤΑΔΙΚΑΣΜΕΝΟΙ παίρνουν μόνιμα +{n1} ΦΟΡΤΙΟ και +{n2} ΜΝΗΜΗ.",
  "Revealed DAMNED gain +{n1} BOUNTY and +{n2} MEMORY, and the gains stay even if they are not revealed next round.": "Οι αποκαλυμμένοι ΚΑΤΑΔΙΚΑΣΜΕΝΟΙ παίρνουν +{n1} ΦΟΡΤΙΟ και +{n2} ΜΝΗΜΗ, και τα κρατούν ακόμα κι αν δεν αποκαλυφθούν τον επόμενο γύρο.",
  "Revealed DAMNED pay double BOUNTY SIN when eliminated.": "Οι αποκαλυμμένοι ΚΑΤΑΔΙΚΑΣΜΕΝΟΙ πληρώνουν διπλή ΑΜΑΡΤΙΑ ΦΟΡΤΙΟΥ όταν εξοντώνονται.",
  "Revealed DAMNED pay {n1}x BOUNTY SIN when eliminated.": "Οι αποκαλυμμένοι ΚΑΤΑΔΙΚΑΣΜΕΝΟΙ πληρώνουν {n1}x ΑΜΑΡΤΙΑ ΦΟΡΤΙΟΥ όταν εξοντώνονται.",
