  "main menu": "αρχικό μενού",
  "no guesses yet": "καμία μαντεψιά ακόμα",
  "nobody has called me that since the fall.": "κανείς δεν με έχει πει έτσι από την πτώση.",
  "non-boss DAMNED with {n1} or more MEMORY take x{n2} damage from all sources.": "Οι ΚΑΤΑΔΙΚΑΣΜΕΝΟΙ που δεν είναι BOSS και έχουν {n1} ή περισσότερη ΜΝΗΜΗ δέχονται x{n2} ζημιά από κάθε πηγή.",
