  "settings.controlsHtml": "<b>Enter</b> Μαντεψιά, Έτοιμος, Επόμενος γύρος &nbsp;·&nbsp; <b>Esc</b> Παύση &nbsp;·&nbsp; <b>Shift</b> περισσότερα σε ένα tooltip",
