  "settings.window.1": "Πλήρης οθόνη",
  "somebody read the fine print.": "κάποιος διάβασε τα ψιλά γράμματα.",
  "the BOUNTY on their head": "το ΦΟΡΤΙΟ που κουβαλάει",
  "the Moon": "Σελήνη",
  "the Sun": "Ήλιος",
  "the next BOSS joining the game with {N}% more SOUL": "το επόμενο BOSS να μπαίνει στο παιχνίδι με {N}% περισσότερη ΨΥΧΗ",
  "undiscovered": "δεν ανακαλύφθηκε",
  "who claims you most": "ποιος σε διεκδικεί περισσότερο",
  "with Satan": "με τον Σατανά",
  "your ARTIFACTS for a round": "τα ΚΕΙΜΗΛΙΑ σου για έναν γύρο",
  "your word that the next BOSS joins the game with {N}% more SOUL": "τον λόγο σου ότι το επόμενο BOSS θα μπει στο παιχνίδι με {N}% περισσότερη ΨΥΧΗ",
  "your {SEAL}": "τη {SEAL} σου",
  "{ASKED} SOUL?": "{ASKED} ΨΥΧΗ;",
  "{COUNT} FAVOR, I see we got a betting man in our midst.": "{COUNT} ΕΥΝΟΙΑ, βλέπω έχουμε έναν τζογαδόρο ανάμεσά μας.",
  "{COUNT} of {ITEM}?": "{COUNT} από {ITEM};",
  "{DEMON} agrees to serve you, but my services are gonna cost ya {PRICE}.": "Ο {DEMON} δέχεται να σε υπηρετήσει, αλλά οι υπηρεσίες μου θα σου κοστίσουν {PRICE}.",
  "{DEMON} doesn't feel like serving you right now.": "Ο {DEMON} δεν έχει όρεξη να σε υπηρετήσει αυτή τη στιγμή.",
  "{DEMON} is a little busy trying to kill you right now.": "Ο {DEMON} είναι λίγο απασχολημένος προσπαθώντας να σε σκοτώσει αυτή τη στιγμή.",
  "{ITEM}?": "{ITEM};",
  "{M} rounds without my Offerings": "{M} γύροι χωρίς τις Προσφορές μου",
  "{NAME}?": "{NAME};",
  "{N} SIN{SIN} is all you can afford.": "{N} ΑΜΑΡΤΙΑ{SIN} είναι ό,τι μπορείς να αντέξεις.",
  "{N} SIN{SIN}, sure can do.": "{N} ΑΜΑΡΤΙΑ{SIN}, φυσικά, γίνεται.",
  "{N} SIN{SIN}": "{N} ΑΜΑΡΤΙΑ{SIN}",
  "{N} drops of your SOUL go on the bill, for the ink.": "{N} σταγόνες από την ΨΥΧΗ σου μπαίνουν στον λογαριασμό, για το μελάνι.",
  "{N} more ARTIFACT use this round?": "{N} ακόμα χρήση ΚΕΙΜΗΛΙΟΥ αυτόν τον γύρο;",
  "{N} of your SOUL": "{N} από την ΨΥΧΗ σου",
  "{N}% more SOUL for the next BOSS": "{N}% περισσότερη ΨΥΧΗ για το επόμενο BOSS",
  "{N}% more pain for {M} rounds": "{N}% περισσότερος πόνος για {M} γύρους",
  "{SEAL} can't get any stronger.": "Η {SEAL} δεν μπορεί να γίνει πιο δυνατή.",
  "{chance}% ELITE": "{chance}% ΕΛΙΤ",
  "{count} / {total} defeated": "{count} / {total} νικήθηκαν",
