  "SEAL of Purson stacks: {n1}.": "Stapel des Siegels des Purson: {n1}.",
  "SEALS hold the power of my demons.": "SIEGEL tragen die Macht meiner Dämonen.",
  "SILENCE{THUNDER}.": "STILLE{THUNDER}.",
