  "SOUL {hp}/{max}": "SEELE {hp}/{max}",
  "STUBBORN DAMNED guesses can only be up to {n1} away from their previous guess.": "Die Tipps STURER VERURTEILTER dürfen höchstens {n1} von ihrem vorherigen Tipp abweichen.",
  "STUBBORN DAMNED take x{n1} damage from all sources.": "STURE VERURTEILTE erleiden x{n1} Schaden aus allen Quellen.",
  "Sacrificial Dagger deals {n1} extra flat damage and appears twice as often in Devil's Offerings.": "Der Opferdolch verursacht {n1} zusätzlichen festen Schaden und erscheint doppelt so oft in den Teufelsgaben.",
  "Sacrificial Dagger deals {n1} extra flat damage and appears {n2}x as often in Devil's Offerings.": "Der Opferdolch verursacht {n1} zusätzlichen festen Schaden und erscheint {n2}x so oft in den Teufelsgaben.",
