  "Show the Codex tab in the Collection with every page, found or not (kept on this device until turned off)": "Zeige den Kodex-Tab in der Sammlung mit jeder Seite, gefunden oder nicht (bleibt auf diesem Gerät, bis du es ausschaltest)",
  "Show the DEAL button now, as if Satan had named it after your first BOSS (kept on this device)": "Zeige jetzt den PAKT-Knopf, als hätte Satan ihn nach deinem ersten BOSS genannt (bleibt auf diesem Gerät)",
  "Show the slot machine and Satan's bets now, as if Satan's first-win speech had been heard (kept on this device)": "Zeige jetzt den Spielautomaten und Satans Wetten, als hättest du Satans Rede zum ersten Sieg gehört (bleibt auf diesem Gerät)",

