  "Big daddy!!!": "¡¡¡Papá grande!!!",
  "Big man!": "¡Hombretón!",
  "Bind a defeated demon in the Collection.": "Ata a un demonio derrotado en la Colección.",
  "Blood, for this?": "¿Sangre, por esto?",
  "Boss Seal": "Sello de Boss",
