  "Bosses": "Bosses",
  "Bounty": "Carga",
  "But I am a busy man, so I'm only gonna come once, and be sure it's gonna cost ya.": "Pero soy un hombre ocupado, así que solo vendré una vez, y ten por seguro que te va a costar.",
  "But I'd like to see {PRICE} first.": "Pero primero me gustaría ver {PRICE}.",
  "But if by chance you came to your senses, I can help you unload the burden of this huge load of SIN{SIN} that would send you to my deepest dungeon.": "Pero si por casualidad has entrado en razón, puedo ayudarte a descargar el peso de este enorme montón de PECADO{SIN} que te mandaría a mi mazmorra más profunda.",
  "But it's not all doom and gloom my beloved minion.": "Pero no todo es pesimismo, mi querido esbirro.",
  "But the clever ones see that coming and guess {n1}, and then the TARGET is {n2}.": "Pero los listos lo ven venir y eligen {n1}, y entonces el OBJETIVO es {n2}.",
  "But you will have to earn it.": "Pero tendrás que ganártelo.",
  "But you, and all other DAMNED to whom I share my gifts will play a very important role.": "Pero tú, y todos los demás CONDENADOS con quienes comparto mis dones, tendréis un papel muy importante.",
  "Buy a Gold Jesus gift": "Compra un don de Oro de Jesús",
  "Buy a SEAL you already own and it turns ELITE, stronger every time.": "Compra un SELLO que ya tengas y se vuelve ÉLITE, más fuerte cada vez.",
  "Buy or upgrade a seal": "Compra o mejora un sello",
  "Buy out three entire shops while Zilon is active in one game": "Compra tres tiendas enteras mientras Zilon está activo en una partida",
  "Buy six seals or artifacts": "Compra seis sellos o artefactos",
  "Buy three seals or artifacts": "Compra tres sellos o artefactos",
  "Buy two artifacts": "Compra dos artefactos",
  "Buy {n1} items (SEALS or ARTIFACTS) in one round": "Compra {n1} objetos (SELLOS o ARTEFACTOS) en una ronda",
  "Buy {n1} items (seals or artifacts) in one round": "Compra {n1} objetos (sellos o artefactos) en una ronda",
  "Buy {price}": "Comprar {price}",
  "Buying an offering resets stacks.": "Comprar una ofrenda reinicia los acumulados.",
