  "Close guesses pay SIN: {n1} at +/-{n2}, adding {n3} per step closer through {n4} at +/-{n5}.": "Los intentos cercanos pagan PECADO: {n1} a +/-{n2}, {n3} más por cada paso más cerca, hasta {n4} a +/-{n5}.",
