  "DAMNED can be revealed more than once a round; each reveal adds a reveal stack, and effects on revealed DAMNED affect them once per stack.": "Los CONDENADOS pueden revelarse más de una vez por ronda; cada revelación añade un acumulado de revelación, y los efectos sobre CONDENADOS revelados los afectan una vez por acumulado.",
  "DAMNED can only be ANALYST or STUBBORN.": "Los CONDENADOS solo pueden ser ANALISTAS o TERCOS.",
