  "DAMNED eliminated": "CONDENADOS eliminados",
  "DAMNED take x{n1} damage from all sources if an ARTIFACT was used on them this round.": "Los CONDENADOS reciben x{n1} de daño de todas las fuentes si se usó un ARTEFACTO sobre ellos esta ronda.",
  "DAMNED take {n1} damage per BOUNTY gained from this SEAL.": "Los CONDENADOS reciben {n1} de daño por cada CARGA obtenida de este SELLO.",
