  "DAMNED with {n1} or less BOUNTY pay double BOUNTY SIN when eliminated.": "Los CONDENADOS con {n1} o menos de CARGA pagan el doble de PECADO de CARGA al ser eliminados.",
  "DAMNED with {n1} or less BOUNTY pay {n2}% BOUNTY SIN when eliminated.": "Los CONDENADOS con {n1} o menos de CARGA pagan un {n2}% de PECADO de CARGA al ser eliminados.",
  "DAMNED with {n1} or more BOUNTY take x{n2} damage from all sources.": "Los CONDENADOS con {n1} o más de CARGA reciben x{n2} de daño de todas las fuentes.",
  "DAMNED with {n1} or more MEMORY pay double BOUNTY SIN when eliminated.": "Los CONDENADOS con {n1} o más de MEMORIA pagan el doble de PECADO de CARGA al ser eliminados.",
