  "Discover {n1} unique seals": "Descubre {n1} sellos distintos",
  "Do we have a deal?": "¿Trato hecho?",
  "Do you know how many ungrateful souls like you appear before me and beg like dogs to be forgiven?": "¿Sabes cuántas almas desagradecidas como tú se presentan ante mí y suplican como perros que las perdonen?",
  "Do you think that stuff grows on trees?": "¿Crees que eso crece en los árboles?",
