  "Don't.": "No lo hagas.",
  "Double the ELITE chance for the SEAL slot for the next {n1} Devil's Offerings rolls.": "Duplica la probabilidad de ÉLITE del hueco de SELLO en las próximas {n1} tiradas de las Ofrendas del Diablo.",
