  "ELITE deals {n1} damage per level to the selected DAMNED.": "ÉLITE inflige {n1} de daño por nivel al CONDENADO elegido.",
  "ELITE deals {n1} damage to every STUBBORN DAMNED per ELITE level.": "ÉLITE inflige {n1} de daño a cada CONDENADO TERCO por nivel de ÉLITE.",
