  "ELITE multiplies only the damage by x{n1} each level, rounded up.": "ÉLITE multiplica solo el daño por x{n1} por nivel, redondeado hacia arriba.",
  "ELITE multiplies the collapse damage by x{n1} each level, rounded up.": "ÉLITE multiplica el daño del derrumbe por x{n1} por nivel, redondeado hacia arriba.",
  "ELITE multiplies the damage by x{n1} and increases the BOUNTY gain by +{n2}%.": "ÉLITE multiplica el daño por x{n1} y aumenta la ganancia de CARGA en +{n2}%.",
  "ELITE multiplies the damage by x{n1} and increases the SIN gained by +{n2}% each level, rounded up.": "ÉLITE multiplica el daño por x{n1} y aumenta el PECADO ganado en +{n2}% por nivel, redondeado hacia arriba.",
  "ELITE multiplies the damage by x{n1} each level, rounded up, and increases the SIN payout by +{n2}%.": "ÉLITE multiplica el daño por x{n1} por nivel, redondeado hacia arriba, y aumenta el pago de PECADO en +{n2}%.",
  "ELITE multiplies the damage by x{n1} each level, rounded up.": "ÉLITE multiplica el daño por x{n1} por nivel, redondeado hacia arriba.",
  "ELITE multiplies the damage outcome by x{n1} each level, rounded up, and increases the SIN outcome by +{n2}%.": "ÉLITE multiplica el resultado de daño por x{n1} por nivel, redondeado hacia arriba, y aumenta el resultado de PECADO en +{n2}%.",
  "ELITE multiplies the echoed damage by x{n1} each level, rounded up.": "ÉLITE multiplica el daño del eco por x{n1} por nivel, redondeado hacia arriba.",
  "ELITE multiplies the excess damage split by x{n1} each level, rounded up.": "ÉLITE multiplica el daño sobrante repartido por x{n1} por nivel, redondeado hacia arriba.",
  "ELITE multiplies the extra damage by x{n1} each level, rounded up.": "ÉLITE multiplica el daño extra por x{n1} por nivel, redondeado hacia arriba.",
  "ELITE multiplies the flat damage by x{n1} each level, rounded up.": "ÉLITE multiplica el daño fijo por x{n1} por nivel, redondeado hacia arriba.",
  "ELITE multiplies the max divisor by x{n1} each level.": "ÉLITE multiplica el divisor máximo por x{n1} por nivel.",
  "ELITE on every SEAL": "ÉLITE en cada SELLO",
  "ELITE pays {n1} SIN each round.": "ÉLITE paga {n1} de PECADO cada ronda.",
  "ELITE raises the payout multiplier by +{n1}%.": "ÉLITE sube el multiplicador de pago en +{n1}%.",
  "ELITE reveals +{n1} more DAMNED each round.": "ÉLITE revela +{n1} CONDENADOS más cada ronda.",
  "ELITE widens the CRITICAL range by +{n1} each level.": "ÉLITE amplía el rango CRITICAL en +{n1} por nivel.",
  "ELITE {level} {name}": "ÉLITE {level} {name}",
  "ELITE: whenever that happens, gain {n1} SIN for each ELITE level.": "ÉLITE: cada vez que esto ocurra, gana {n1} de PECADO por cada nivel de ÉLITE.",
  "ELITE: x{n1} damage each level.": "ÉLITE: x{n1} de daño por nivel.",
  "Each ELITE level adds +{n1} more to both.": "Cada nivel de ÉLITE añade +{n1} más a ambos.",
  "Each POISON deals {n1} damage at the end of every round.": "Cada VENENO inflige {n1} de daño al final de cada ronda.",
  "Each round, every revealed DAMNED has a {n1}% chance to take x{n2} damage from all sources.": "Cada ronda, cada CONDENADO revelado tiene un {n1}% de probabilidad de recibir x{n2} de daño de todas las fuentes.",
  "Each round, {n1}% chance to reveal one extra DAMNED.": "Cada ronda, {n1}% de probabilidad de revelar a un CONDENADO extra.",
  "Each symbol pays for how many of it came up.": "Cada símbolo paga según cuántas veces salió.",
  "Earn it first, then we'll talk.": "Gánatelo primero, luego hablamos.",
  "Earn {n1} SIN this round": "Gana {n1} de PECADO esta ronda",
  "Either way you are an enormous virgin!": "¡En cualquier caso eres un virgen enorme!",
