  "Settings": "Ajustes",
  "Seventh Pentacle of Saturn": "Séptimo Pentáculo de Saturno",
  "Shares one SEAL slot with the other Trinity SEALS (together, the SEAL of God).": "Comparte un hueco de SELLO con los otros SELLOS de la Trinidad (juntos, el SELLO de Dios).",
  "Shop": "Tienda",
  "Should He deny you a servant of His, do not plead.": "Si Él te niega a uno de Sus siervos, no supliques.",
  "Show the game in this language, finished or not (missing text shows in English; Pseudo marks text that is not translatable yet)": "Mostrar el juego en este idioma, esté terminado o no (lo que falta se ve en inglés; Pseudo marca el texto que aún no se puede traducir)",
  "Shut your sacrilegious fucking mouth.": "Cierra tu jodida boca sacrílega.",
  "Six is all you can get and the price is {PRICE}.": "Seis es todo lo que puedes tener y el precio es {PRICE}.",
  "Sixth Pentacle of Saturn": "Sexto Pentáculo de Saturno",
  "Skip past the eight special bosses": "Salta los ocho bosses especiales",
  "Slot machine and Satan's bet": "Tragaperras y apuesta de Satanás",
  "Slot machine · {cost} a spin": "Tragaperras · {cost} por tirada",
  "So be thankful for once you are even getting the chance to prove yourself before me.": "Así que, por una vez, agradece que tengas siquiera la oportunidad de demostrar lo que vales ante mí.",
  "So for an ELITE {OTHER} it's gonna run you {PRICE}.": "Así que un ÉLITE para {OTHER} te va a costar {PRICE}.",
  "So listen here, I got you a little offer.": "Así que escucha, te tengo una pequeña oferta.",
  "So please, just send me back and I promise I will do good this time.": "Así que, por favor, devuélveme y te prometo que esta vez haré el bien.",
  "So please, keep the SIN flowing and the sinners screaming, and maybe we shall meet again.": "Así que, por favor, que siga fluyendo el PECADO y gritando los pecadores, y quizá nos volvamos a ver.",
  "So you guess {GUESS}.": "Así que eliges {GUESS}.",
  "So you want your second chance that bad?": "¿Tanto quieres tu segunda oportunidad?",
  "So, what does your wretched heart desire?": "Y bien, ¿qué desea tu miserable corazón?",
  "Solomon's pentacles?": "¿Los pentáculos de Salomón?",
  "Some want a victim: use it, then click the DAMNED you want it on.": "Algunos quieren una víctima: úsalo y luego haz clic en el CONDENADO sobre el que lo quieras.",
  "Somebody's planning a party.": "Alguien está planeando una fiesta.",
  "Somebody's planning to make some moves I see.": "Veo que alguien planea hacer algunos movimientos.",
