  "beat the {n1} BOSSES": "vence a los {n1} BOSS",
  "being a true and terrible account of how one bargains with the Adversary, set down by those who bargained and lost, for those who will.": "siendo un verdadero y terrible relato de cómo se negocia con el Adversario, escrito por quienes negociaron y perdieron, para quienes lo harán.",
