  "On: the Codex tab shows every page.": "Activado: la pestaña del Códice muestra todas las páginas.",
  "Click to go back to the pages really found": "Haz clic para volver a las páginas encontradas de verdad",
  "Show the Codex tab in the Collection with every page, found or not (kept on this device until turned off)": "Muestra la pestaña del Códice en la Colección con todas las páginas, encontradas o no (se guarda en este dispositivo hasta que lo apagues)",
  "Show the DEAL button now, as if Satan had named it after your first BOSS (kept on this device)": "Muestra ahora el botón PACTO, como si Satanás lo hubiera nombrado tras tu primer BOSS (se guarda en este dispositivo)",
  "Show the slot machine and Satan's bets now, as if Satan's first-win speech had been heard (kept on this device)": "Muestra ahora la tragaperras y las apuestas de Satanás, como si hubieras oído el discurso de Satanás por la primera victoria (se guarda en este dispositivo)",

