  "Best run {name}": "最佳对局：{name}",
  "Big daddy!!!": "大老爹！！！",
  "Big man!": "大人物！",
  "Bind a defeated demon in the Collection.": "在收藏中束缚一个已击败的恶魔。",
  "Blood, for this?": "为了这个，献血？",
  "Boss Seal": "BOSS之印",
  "Boss Seals": "BOSS之印",
  "Bosses": "BOSS",
  "Bounty": "负担",
  "But I am a busy man, so I'm only gonna come once, and be sure it's gonna cost ya.": "不过我是个大忙人，所以只来一次，而且你可以确定，这要付出代价。",
  "But I'd like to see {PRICE} first.": "不过我想先看到{PRICE}。",
  "But if by chance you came to your senses, I can help you unload the burden of this huge load of SIN{SIN} that would send you to my deepest dungeon.": "不过如果你碰巧恢复了理智，我可以帮你卸下这一大堆罪孽{SIN}的重担，否则它会把你送进我最深的地牢。",
  "But it's not all doom and gloom my beloved minion.": "不过也不全是坏事，我亲爱的爪牙。",
  "But the clever ones see that coming and guess {n1}, and then the TARGET is {n2}.": "但聪明人早就料到，于是猜{n1}，那目标就变成了{n2}。",
  "But you will have to earn it.": "但你得自己挣来。",
  "But you, and all other DAMNED to whom I share my gifts will play a very important role.": "但你，以及所有我分享恩赐的其他罪人，都将扮演非常重要的角色。",
  "Buy a Gold Jesus gift": "购买一个黄金耶稣恩赐",
  "Buy a SEAL you already own and it turns ELITE, stronger every time.": "购买一个你已拥有的印记，它就会变成精英，每次都更强。",
  "Buy or upgrade a seal": "购买或升级一个印记",
  "Buy out three entire shops while Zilon is active in one game": "在一局中齐隆在场时买空整整三个商店",
  "Buy six seals or artifacts": "购买六个印记或法器",
  "Buy three seals or artifacts": "购买三个印记或法器",
  "Buy two artifacts": "购买两个法器",
  "Buy {n1} items (SEALS or ARTIFACTS) in one round": "在一回合内购买{n1}件物品（印记或法器）",
  "Buy {n1} items (seals or artifacts) in one round": "在一回合内购买{n1}件物品（印记或法器）",
  "Buy {price}": "购买 {price}",
  "Buying an offering resets stacks.": "购买一件献礼会重置叠层。",
  "CRITICALS in a row": "连续CRITICAL",
  "Calc:": "计算：",
  "Can't say I blame him.": "不能怪他。",
  "Cannot be upgraded.": "无法升级。",
