  "Challenges": "挑战",
  "Changed your mind?": "改主意了？",
  "Cheating death, now that's my kind of deal.": "欺骗死亡，这才是我喜欢的交易。",
  "Clear the search": "清除搜索",
  "Close The Tab To Leave The Table.": "关闭标签页以离开牌桌。",
  "Close guesses pay SIN: {n1} at +/-{n2}, adding {n3} per step closer through {n4} at +/-{n5}.": "接近的猜测支付罪孽：+/-{n2}时{n1}，每接近一步多{n3}，直到+/-{n5}时{n4}。",
  "Close": "关闭",
  "Codex": "法典",
  "Collection": "收藏",
  "Complete a Deal": "完成一次交易",
  "Complete {n1} Deals": "完成{n1}次交易",
  "Consider it done, but it's still gonna cost ya {PRICE}.": "就当办好了，不过还是要花你{PRICE}。",
  "Consider it done, your bill is {PRICE}.": "就当办好了，你的账单是{PRICE}。",
  "Converted amounts are not converted again.": "已转化的数量不会再次转化。",
  "Copies a random SEAL you own.": "复制一个你拥有的随机印记。",
  "Corrupted Crystal": "腐化水晶",
  "Count your blessings, you have few.": "数数你的福分吧，少得可怜。",
  "Count your own guess in and the TARGET lands on {TARGET}.": "把你自己的猜测也算进去，目标就落在{TARGET}。",
  "Credits": "制作人员",
  "Critical": "Critical",
  "Current damage: {n1}.": "当前伤害：{n1}。",
  "Cursed Chalice": "诅咒圣杯",
  "DAMAGE is % of max SOUL to every DAMNED, dealt at the end of the next round.": "伤害为每个罪人最大灵魂的%，在下一回合结束时造成。",
  "DAMAGE": "伤害",
  "DAMNED CRITICAL damage cannot hurt you.": "罪人的CRITICAL伤害无法伤到你。",
  "DAMNED already STUBBORN take {n1}% extra damage this round.": "已是固执者的罪人本回合额外受到{n1}%伤害。",
  "DAMNED can be revealed more than once a round; each reveal adds a reveal stack, and effects on revealed DAMNED affect them once per stack.": "罪人每回合可以被揭示不止一次；每次揭示增加一层揭示叠层，作用于已揭示罪人的效果每层生效一次。",
  "DAMNED can only be ANALYST or STUBBORN.": "罪人只能是分析者或固执者。",
  "DAMNED can only have two personalities: ANALYST or STUBBORN.": "罪人只能有两种性格：分析者或固执者。",
  "DAMNED eliminated": "被淘汰的罪人",
  "DAMNED take x{n1} damage from all sources if an ARTIFACT was used on them this round.": "若本回合有法器作用于罪人，他们受到所有来源的伤害x{n1}。",
  "DAMNED take {n1} damage per BOUNTY gained from this SEAL.": "罪人每从此印记获得1点负担，就受到{n1}点伤害。",
  "DAMNED with the STUBBORN personality take x{n1} damage from all sources.": "性格为固执者的罪人受到所有来源的伤害x{n1}。",
  "DAMNED with {n1} or less BOUNTY pay double BOUNTY SIN when eliminated.": "负担不超过{n1}的罪人被淘汰时支付双倍负担罪孽。",
  "DAMNED with {n1} or less BOUNTY pay {n2}% BOUNTY SIN when eliminated.": "负担不超过{n1}的罪人被淘汰时支付{n2}%负担罪孽。",
  "DAMNED with {n1} or more BOUNTY take x{n2} damage from all sources.": "负担达到{n1}或以上的罪人受到所有来源的伤害x{n2}。",
  "DAMNED with {n1} or more MEMORY pay double BOUNTY SIN when eliminated.": "记忆达到{n1}或以上的罪人被淘汰时支付双倍负担罪孽。",
  "DAMNED with {n1} or more MEMORY pay {n2}x BOUNTY SIN when eliminated.": "记忆达到{n1}或以上的罪人被淘汰时支付{n2}倍负担罪孽。",
  "DEV": "DEV",
  "Damage dealt": "造成的伤害",
  "Damage in one round": "单回合伤害",
  "Dare.": "有种你就来。",
  "Dark Talisman": "黑暗护符",
  "Darling, I already own that.": "亲爱的，那个我已经有了。",
  "Deal {n1}% max-SOUL damage to non-boss DAMNED, or {n2}% to BOSSES.": "对非BOSS罪人造成其最大灵魂{n1}%的伤害，对BOSS则为{n2}%。",
  "Deepest descent": "最深下降",
  "Defeat a Boss": "击败一个BOSS",
  "Defeat an Archangel": "击败一位天使长",
  "Defeat {n1} BOSSES other than Pyros that have been granted a PYROS-TECH ability in total": "共击败{n1}个获得了PYROS-TECH能力的BOSS（皮洛斯除外）",
  "Defeat {n1} Bosses other than Pyros that have been granted a PYROS-TECH ability in total": "共击败{n1}个获得了PYROS-TECH能力的Boss（皮洛斯除外）",
  "Demonic Idol": "恶魔偶像",
  "Demons slain": "已斩杀的恶魔",
  "Descent": "下降",
  "Devil's Offerings has one more ARTIFACT slot.": "恶魔献礼多一个法器栏位。",
  "Devil's Offerings has {n1} slots.": "恶魔献礼有{n1}个栏位。",
  "Devil's Offerings is still available before you advance.": "在你前进之前，恶魔献礼仍然开放。",
  "Did your mother never teach you manners?": "你妈妈没教过你礼貌吗？",
  "Discover {n1} unique SEALS": "发现{n1}个不同的印记",
  "Discover {n1} unique seals": "发现{n1}个不同的印记",
  "Do we have a deal?": "成交吗？",
  "Do you know how many ungrateful souls like you appear before me and beg like dogs to be forgiven?": "你知道有多少像你这样忘恩负义的灵魂出现在我面前，像狗一样乞求宽恕吗？",
  "Do you think that stuff grows on trees?": "你以为这东西是树上长出来的吗？",
  "Does your avarice know no limit?": "你的贪婪没有止境吗？",
  "Don't buy any Devil's Offerings": "不从恶魔献礼购买任何东西",
  "Don't eliminate any Damned": "不淘汰任何罪人",
  "Don't get a KO for {n1} consecutive rounds": "连续{n1}回合不取得KO",
  "Don't get your hopes too high up now tho buddy.": "不过别抱太大希望，伙计。",
  "Don't have the worst Guess at reveal": "揭示时猜测不是最差的",
  "Don't leave me hanging!": "别把我晾在这儿！",
  "Don't like what's on offer?": "不喜欢现在的货？",
  "Don't push your luck, and back to work!": "别得寸进尺，回去干活！",
  "Don't use artifacts this round": "本回合不使用法器",
  "Don't you start getting greedy with me my little pawn.": "别开始在我面前贪心，我的小棋子。",
  "Don't.": "别。",
  "Double the ELITE chance for the SEAL slot for the next {n1} Devil's Offerings rolls.": "在接下来{n1}次恶魔献礼刷新中，使印记栏位出现精英的概率翻倍。",
  "Dr Dee's Crystal": "迪伊博士的水晶",
  "Dr Dee's Gold Disc": "迪伊博士的金盘",
  "During reveal, add {n1} to the TARGET.": "揭示时，目标加{n1}。",
  "During reveal, reduce the TARGET by {n1}.": "揭示时，目标减{n1}。",
  "ELITE adds +{n1} BOUNTY to the reveal reward.": "精英使揭示奖励+{n1}负担。",
  "ELITE adds +{n1} BOUNTY to the spread each level.": "精英每级使分配量+{n1}负担。",
  "ELITE adds +{n1} CRITICAL damage.": "精英使CRITICAL伤害+{n1}。",
  "ELITE adds +{n1} MEMORY each round per level.": "精英每级每回合+{n1}记忆。",
  "ELITE adds +{n1} POISON to each DAMNED on your CRITICAL each level.": "精英每级在你CRITICAL时给每个罪人+{n1}毒素。",
  "ELITE adds +{n1} damage and +{n2} BOUNTY to the Lamb each level.": "精英每级使羔羊+{n1}伤害和+{n2}负担。",
  "ELITE adds +{n1} to both end-of-round gains.": "精英使两项回合结束收益都+{n1}。",
  "ELITE adds +{n1} to the multiplier.": "精英使倍率+{n1}。",
