  "For every {n1} SIN spent this round, deal {n2} damage to the highest-SOUL DAMNED.": "本回合每花{n1}罪孽，对灵魂最高的罪人造成{n2}点伤害。",
  "For every {n1} SIN you spend in a round, deal {n2} damage to the highest-SOUL DAMNED.": "一回合内每花{n1}罪孽，对灵魂最高的罪人造成{n2}点伤害。",
